import assert from "node:assert/strict";
import { createTurnIo, failingJob, okJob } from "./support/turn-io.mjs";

/**
 * FROZEN behaviour scenarios for the async pipeline. Do not edit this file — it is the evidence the repair is
 * graded on, and the verifier checks its content digest on every run.
 *
 * Every scenario drives time and ordering through the injected IO seam in `support/turn-io.mjs`. No scenario waits
 * on a real timer, sleeps, or races the event loop: parked callers are released one at a time, in the order they
 * parked, so a failure here is a defect and never flake.
 */

const pipeline = () => import("../src/pipeline.mjs");
const sinkModule = () => import("../src/sink.mjs");
const metricsModule = () => import("../src/metrics.mjs");

/** Run the pipeline to completion, capturing what the sink looked like the instant it resolved. */
async function runCapturing(jobs) {
	const { runPipeline } = await pipeline();
	const { createSink } = await sinkModule();
	const { createMetrics } = await metricsModule();
	const turn = createTurnIo();
	const sink = createSink(turn.io);
	const metrics = createMetrics();
	let atResolve = null;
	const running = runPipeline(jobs, { io: turn.io, sink, metrics }).then((result) => {
		atResolve = { ids: sink.records.map((entry) => entry.id), inFlight: sink.inFlight };
		return result;
	});
	await turn.drain();
	const result = await running;
	return { result, sink, metrics, atResolve };
}

export const scenarios = [
	{
		id: "the-sink-is-complete-when-the-pipeline-resolves",
		title: "runPipeline does not resolve while a sink write it started is still in flight",
		async check() {
			const jobs = [okJob("j1", 10), okJob("j2", 20), okJob("j3", 30)];
			const { atResolve } = await runCapturing(jobs);
			assert.equal(
				atResolve.inFlight,
				0,
				`runPipeline resolved with ${atResolve.inFlight} sink write(s) still in flight — it started work it never waited for`,
			);
			assert.deepEqual(
				atResolve.ids,
				["j1", "j2", "j3"],
				"every successful job must be in the sink before runPipeline resolves",
			);
		},
	},
	{
		id: "the-sink-keeps-job-order-and-skips-failures",
		title: "with jobs of uneven cost and one failure, the sink holds the survivors in job order",
		async check() {
			const jobs = [
				okJob("slow", "a", 4),
				failingJob("boom", "disk on fire", 1),
				okJob("fast", "b", 1),
				okJob("slower", "c", 6),
			];
			const { atResolve } = await runCapturing(jobs);
			assert.equal(atResolve.inFlight, 0, "runPipeline resolved with a sink write still in flight");
			assert.deepEqual(
				atResolve.ids,
				["slow", "fast", "slower"],
				"the sink must hold exactly the successful jobs, in job order — a job that threw has no value to write",
			);
		},
	},
	{
		id: "a-failing-job-is-reported-as-failed",
		title: "a job that throws is reported with status failed, its message, and its id in `failed`",
		async check() {
			const jobs = [okJob("before", 1), failingJob("boom", "disk on fire", 2), okJob("after", 2)];
			const { result } = await runCapturing(jobs);
			assert.deepEqual(
				result.failed,
				["boom"],
				"the id of every job that threw belongs in `failed` — a swallowed error is still a failure",
			);
			const entry = result.results.find((candidate) => candidate.id === "boom");
			assert.ok(entry, "the failing job must still get a result entry");
			assert.equal(entry.status, "failed", "the failing job's status must be `failed`, not `ok`");
			assert.equal(entry.error, "disk on fire", "the thrown message must survive into the result");
		},
	},
	{
		id: "a-failure-does-not-hide-the-other-results",
		title: "the jobs around a failure still run and are still reported as successes",
		async check() {
			const jobs = [okJob("a", "A", 1), failingJob("x", "nope", 3), okJob("b", "B", 2), failingJob("y", "also nope", 1)];
			const { result } = await runCapturing(jobs);
			assert.deepEqual(
				result.results.map((entry) => entry.id),
				["a", "x", "b", "y"],
				"every job gets exactly one result, in job order",
			);
			const ok = result.results.filter((entry) => entry.status === "ok");
			assert.deepEqual(
				ok.map((entry) => [entry.id, entry.value]),
				[
					["a", "A"],
					["b", "B"],
				],
				"only the jobs that returned may be reported as successes, and they keep their values",
			);
		},
	},
	{
		id: "concurrent-records-of-one-key-do-not-lose-updates",
		title: "three concurrent records of one key add three",
		async check() {
			const { countOf, createMetrics, record } = await metricsModule();
			for (const concurrency of [2, 3, 8]) {
				const turn = createTurnIo();
				const metrics = createMetrics();
				const running = Promise.all(
					Array.from({ length: concurrency }, () => record(metrics, "hits", { io: turn.io })),
				);
				await turn.drain();
				await running;
				assert.equal(
					countOf(metrics, "hits"),
					concurrency,
					`${concurrency} concurrent records must add ${concurrency}, not ${countOf(metrics, "hits")} — increments are being lost`,
				);
			}
		},
	},
	{
		id: "interleaved-records-across-keys-stay-exact",
		title: "concurrent records of different keys each land in full",
		async check() {
			const { countOf, createMetrics, record } = await metricsModule();
			const pattern = ["a", "b", "a", "c", "a", "b", "c", "c", "c"];
			const turn = createTurnIo();
			const metrics = createMetrics();
			const running = Promise.all(pattern.map((key) => record(metrics, key, { io: turn.io })));
			await turn.drain();
			await running;
			for (const key of ["a", "b", "c"]) {
				const expected = pattern.filter((candidate) => candidate === key).length;
				assert.equal(
					countOf(metrics, key),
					expected,
					`key \`${key}\` was recorded ${expected} times but the tally says ${countOf(metrics, key)}`,
				);
			}
		},
	},
];
